INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (816, 13, 'LS265129A', 'supply of 120sq.mm, 4 core, aluminium conductor, xlpe insulated armoured ltug cable(technical spe cification enclosed). [ warranty period: 30 months after the date of delivery ] [quantity tolerance (+/-): 5 %age , item category : normal , total po value variation permitted: max 8 lacs ] ]', '2026-06-30 00:00:00', 'Krishna, Andhra Pradesh, India', 'South Central Railway', '0', '0', '-', NULL, NULL, '1. Copies of R Notes/CRAC/Proof of acceptance of material by consignee2. Udyam Registration Certificate3. MSE certificate4. Tender specific authorization from OEM5. UDYAM Registration Certificate6. GST Registration Number7. Service Tax Registration Certificate8. Manufacturing premises inspection confirmation letter9. Manufacturer''s Test and Guarantee Certificate10. Manufacturer''s authorization letter11. Copy of PAN Card12. Chartered Accountant Certificate regarding turnover13. Copies of IT returns for the two preceding years14. GST compliant bill/invoice15. Proof of download of tender documents16. Bank Guarantee17. MSE Certificate for EMD exemption18. Proof of MSE registration19. Documentary evidence for Tender eligibility criteria20. Documentary evidence for Instructions to Tenderers and General Conditions of Tender21. Offered description as per tender description22. Documentary evidence for MSE to get benefit/preference under Public Procurement Policy23. Manufacturer''s Test and Guarantee Certificate24. Authorization Letter from OEM25. MSE Certificate26. Copy of Purchase Order27. Copy of Receipted Challan28. Copy of Inspection Certificate29. Documentary evidence for payment of tender document cost30. Copy of MSE certificate for tender document cost exemption', '2026-07-11 09:27:46.237', '2026-07-11 09:27:46.237', NULL, NULL, 'date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101339697', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (817, 13, '52265775', 'supply of central conductor of copper for circular magnetization of hollow part and spring part no. ke-cc-1000 for k-electronics make electromagnetic crack detecting machine, model: magnatest unmt-18000 lhb, make: k-electronics or its equivalent. [ war ranty period: 12 months after the date of delivery ] ]', '2026-06-28 00:00:00', 'Tiruchirappalli, Tamil Nadu, India', 'Southern Railway', '0', '0', '-', NULL, NULL, '1. MSE certificate2. OEM dealership certificate3. Proof of supply of same/similar item to any Zonal Railways/ Railway Production Units4. registration by the competent authority', '2026-07-11 09:27:46.49', '2026-07-11 09:27:46.49', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101341545', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (818, 13, '50263017', 'supply of self-supporting pvc drop wire with fibre glass roving as strength member, conductor dia meter nominal 0.5 mm, number of pair- 1 pair spec: tec specification gr/wir-03/03.aug 2006 or late st [ warranty period: 30 months after the date of delivery ] [quantity tolerance (+/-): 5 %age , item category : normal , total po value variation permitted: max 8 lacs ] ] divisional gsd adra, ser', '2026-07-09 00:00:00', 'Adra, West Bengal, India', 'South Eastern Railways', '0', '0', '-', NULL, NULL, '1. Purchase Order along with Inspection certificate and receipt note / certificate2. Tender specific authorization in proper format3. Udyam Registration Certificate4. IRS Conditions of Contract5. General Conditions of Contract6. Copy of Purchase Order along with Inspection certificate and receipt note / certificate7. GSTIN details8. MSE benefits related documents (if applicable)', '2026-07-11 09:27:46.74', '2026-07-11 09:27:46.74', 'The tender brief refers to self-supporting PVC drop wire, which is not listed among the specified products such as power cables or conductors.', false, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101342479', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
