INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (821, 13, '92265166A', 'supply of thin walled flexible elastomeric cable single core with copper conductors for working voltage above 750v up to 1.8kv/3kv conforming to rdso specification no. elrs/spec/elc/0019, rev-4 or latest, si ze-2.5 sq. mm. colour: red & black in equal quantity of length. [ warranty period: 30 months after the date of delivery ] ]', '2026-06-25 00:00:00', 'Bhubneshwar, Orissa, India', 'East Coast Railway', '0', '0', '-', NULL, NULL, NULL, '2026-07-11 09:27:47.49', '2026-07-11 09:27:47.49', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101343702', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1094, 17, '952104-E. Proc.No.35/2026-27', 'replacement of existing aaac dog conductor with htls  conductor non metallic core having cfcc carbon fibre composite core technology equivalent to dog conductor in 132kv tadepalli-guntur sc line from loc no 1 to 106 including supply of  conductor and its connected line hardware, erection, stringing, testing and commissioning of 132kv sc line along with bay modification works on both ends in guntur district', '2026-07-16 18:30:00', 'Guntur, Andhra Pradesh, India', 'Transmission Corporation Of Andhra Pradesh Limited', '0', '0', '-', NULL, NULL, NULL, '2026-07-13 07:01:56.819', '2026-07-13 07:19:40.166', 'The tender explicitly involves the supply of HTLS conductors, which is listed as an eligible product.', true, 'cable,conductors', NULL, '129427583', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101756092', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (786, 13, '51261495', 'supply of 150 sq.mm black and red colour in equal quantity electron beam irradiation curing process or chemic al curing process thin walled flexible elastomeric cable with copper conductor suitable for rolling stock application c onforming to rdso spec.no. elrs/spec/elc/oo19, rev.4, feb-2018, 1.8 kv grade. note: 1) item/type/model/make/brand from the manufacturer/suppliers as approved by rdso shall only be co nsidered. 2. cables shall be supplied in coils of 100 metres length with a tolerance of +/-5% on the length. 3. firm shall indicate the curing process (e?beam irradiation (or) chemical curing) in their of fer as per drg.no. rdso spec no. elrs/spec/elc/0019 rev-4 0f feb 2018 specn: rdso spec no. elrs/spec/elc/00 19 rev-4 0f feb 2018. [ warranty period: 30 months after the date of delivery ] [quantity tolerance (+/-): 5 %age , item category : normal , total po value variation permitted: max 8 lac s ] ]', '2026-07-14 00:00:00', 'Jhansi, Uttar Pradesh, India', 'North Central Railway', '0', '0', '-', NULL, NULL, '• MSEs who are interested in availing themselves the benefits/preferential treatment will upload with their offer, the proof of their being registered under Udyam Registration as MSE unit.
• MSEs must also indicate the terminal validity date of their registration.
• Bidder should submit Authorized OEM/Dealership Certificate of Authorized Dealer along with their offer.
• Certificate of Authorization from the manufacturer, as per proforma given in Annexure-4
• Performance Statement template
• Statement in PDF format indicating details of equipment, staff employed and quality control measures, as per Annexure-3
• Valid Digital Signature Certificate
• Self-certification regarding Domestic Value Addition (Form1, Annexure-8)
• Affidavit of self-certification regarding domestic value addition (Annexure-12)
• Bidder must submit a certificate as per Annexure-19
• Bid securing declaration (Annexure 16)', '2026-07-11 09:27:38.465', '2026-07-11 09:27:38.465', 'The tender is for flexible elastomeric cables, which are explicitly excluded from eligibility.', false, 'cable,conductors', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101988269', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (787, 13, '2026_APGCL_52952_1', 'corrigendum : supply, installation, testing, and commissioning of gas turbine generator skid control and auxiliary cables - supply, installation, testing, and commissioning of gas turbine generator skid control and auxiliary cables for unit #5 at lakwa thermal power station, apgcl', '2026-07-17 00:00:00', 'Sivasagar, Assam, India', 'Assam Power Generation Corporation Limited', '500', '54000', '-', NULL, NULL, '• Letter of Bid (FORM-B1)
• Bidder Information (FORM-B2)
• Manufacturer''s Authorization Letter (FORM-B3)
• Details of Work Done by Bidder (FORM-B4)
• Certificate on Financial Strength (FORM-B5)
• Power of Attorney for Signing of Bid (FORM-B6)
• Undertaking by the Bidder (FORM-B7)
• Self-Undertaking on Statutory Tax Compliance (FORM B9)
• Checklist of Documents Submitted along with Technical Bid (FORM-B10)
• Copy of PAN Card
• EPF Registration
• GST Registration Certificate of the bidder''s Firm
• Certificate of registration of the Firm (in case of Solo Proprietor)
• Certificate of Incorporation (in case of Company)
• Joint Venture Agreement
• Bank Guarantee Format for Bid Security (EMD) (FORMAT-B8)
• Documents related to bidder''s eligibility and past experience
• Documents related to the bidder''s average annual Turnover, Net Worth during 03 (three) Financial Years (FY 2022-23, 2023-24 & 2024-25) certified by a Chartered Accountant
• Signed & Sealed Confirmation from Bidder stating that they had quoted for all items (entire bidder''s scope) required as per Tender Clause Section-IV: Schedule of Requirements)/BoQ1.
• Technical documents of the offered products (as per Clause 7.5)
• Type Test Report of offered Cables
• Payment proof of EMD
• Authorization Letter in case the bidder is not the manufacturer
• Statutory document of Manufacturer of the offered materials along with address details
• All Bidding forms (B1 to B10)
• All other documents as sought in this Tender
• Any other document as deemed necessary as per this tender of APGCL
• Certificate of Common Criteria as per ISO/IEC 15408 issued by signatories of the Common Criteria Recognition Agreement (CCRA)
• Manufacturer''s certifications for supply chain management system practices and secure product development process implementations based on any one or more of standards ISO / IEC 27036, ISO / IEC 20243, IEC 62443
• Type Test Reports or standard factory routine/acceptance test certificates for the offered cable categories
• Test reports issued by independent national/international testing laboratories, such as CPRI, ERDA, NABL, or equivalent, or by the manufacturer''s ISO-certified in-house testing facility
• Manufacturer''s Authorization Form (MAF) from an established cable manufacturer
• Technical data sheets of the offered cables
• Type Test Certificates
• Audited Statement of Accounts/Chartered Accountant Certified Financial Documents (Balance Sheet, P&L Statement, Cash Flow Statement) for last three financial years ending on 31/03/2025
• Certificate of Incorporation
• Partnership Deed
• GST Registration Certificate
• Any equivalent registration document clearly indicating that the business has been in operation for at least 3 (three) years
• Work Order / Contract Agreement / Purchase Order
• Corresponding Completion Certificate or client-certified performance report confirming successful execution
• Relevant financial documents viz. Balance Sheet, Profit & Loss Statement, ITR, etc. of the 03 (three) financial years, FY 2022-23, 2023-24 & 2024-25
• Certified copy from the Chartered Accountant or Audited Financial Report for FY 2022-23, 2023-24 & 2024-25
• Signed declaration confirming that calibrated testing equipment, such as Insulation Resistance/Megger testers, Digital Multimeters, suitable crimping tools, and other required tools, shall be deployed at site during execution', '2026-07-11 09:27:38.716', '2026-07-11 09:27:38.716', 'The tender brief includes only the installation, testing, and commissioning of cables, without explicitly mentioning the supply of eligible products listed.', false, 'cable,conductors', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101994571', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (788, 13, '08265202', 'supply of pvc insulated armoured, unscreened, underground railway signaling cable copper con ductor as per specification no.irs:s-63/2014 (rev.4.0) or latest amendment as on the date of opening of tender, size 6 core x 1.5 sq.mm. [ warranty period: 30 months after the date of delivery ] [quantity tolerance (+/-): 2 %age , item category : special (signaling cables) , total po value variation permitted: not applicable ] ]', '2026-08-03 00:00:00', 'New Delhi, Delhi, India', 'Northern Railway', '0', '2000000', '-', NULL, NULL, '• Tender specific authorization from the approved vendors/developmental vendors/Manufacturers
• Registration with the Competent Authority (for bidders from countries sharing a land border with India)
• Certificate of registration (for bidders from countries sharing a land border with India)
• Local Content percentage self-certification
• Certificate from statutory auditor or cost auditor of the company (for contracts > Rs. 10 Crores)
• Certificate from a practicing cost accountant or practicing chartered accountant (for contracts > Rs. 10 Crores)
• Scanned copy in PDF format of valid UDYAM certificate
• Scanned copy in PDF format of registration/approval certificate (if approved by RDSO/ PUs/CORE)
• Scanned copies of documents in PDF format in the Attach Documents template on ''Techno-commercial Bid Details'' form (if not registered with Northern Railway or UDYAM, or not an approved source)
• Manufacturer''s authorization certificate
• Performance Statement template
• Annexure-3: Proforma for Performance Statement
• Statement of equipment, staff employed and quality control measures
• Annexure-4: Proforma for Equipment and Quality Control
• Digital Signature Certificate
• Valid registration certificate issued by any of the authorities detailed at Para 2.4.1 (i) (for MSE status)
• Bid Securing Declaration
• Annexure-5: Proforma for Manufacturer Authorization Form
• Annexure-6: Proforma for NEFT Mandate Form
• Annexure-7: FORMAT OF DEBARMENT PROPOSAL FROM PROCURING RAILWAY UNIT
• Annexure-8: FORMAT for SHOW CAUSE NOTICE
• Annexure-9: FORMAT OF DEBARMENT ORDER
• Annexure-10: Guidelines on Debarment of firms from Bidding
• Annexure-1: PROFORMA FOR BANK GUARANTEE FOR CONTRACT PERFORMANCE GUARANTEE
• Annexure-2: No Claim Certificate
• IRS Conditions of Contract
• Instructions to Tenderers for Electronic Tenders
• NIT and Tender Document
• ''Techno Commercial Bid Details'' form
• ''Financial Rate Page for Supply'' form
• Copies of purchase order for a minimum of 20 percent of the total tender quantity or multiple orders totaling to 20% or more of the tender quantity (for approved sources)
• Documented past performance reports of same or similar items (for developmental orders)
• Details of M&P, testing facilities, QAP, technical manpower available (for developmental orders)
• Registration for same/similar item(s) with other Government agencies or PSUs etc. (for developmental orders)
• Income Tax PAN details
• Photocopy of Income Tax PAN details', '2026-07-11 09:27:38.967', '2026-07-11 09:27:38.967', 'The tender is for PVC insulated underground railway signaling cables, which are not included in the eligible products list.', false, 'conductors', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102006022', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
