INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (790, 13, '957577-M100030964P212', 'dr.nttps-supply of telephone cables', '2026-07-19 00:00:00', 'Krishna, Andhra Pradesh, India', 'Andhra Pradesh Power Generation Corporation Limited', '0', '0', '-', NULL, NULL, '• Authorization Letter (Manufacturer''s)
• Technical Specifications
• Proforma for Terms & Conditions
• List of customers in the power sector
• Copies of Purchase Orders
• Performance certificates
• Deviation certificate
• Certificate of Conformance
• Eyeletted label of thick paper with linen inside securely attached to the inner part by means of sort copper wire
• Label with information of maker''s name, year of manufacture, coil number and weight of coil
• ISI certification mark
• Permanent Account Number (PAN) card
• Copy of latest income tax returns submitted along with the proof of receipt
• New price list
• Recently executed orders to power sector
• Copy of rate contract
• Copy of certificate (NSIC/SSI Registration)
• Proforma for Terms and Conditions
• Statement of deviation
• E-procurement platform registration
• Digital certificate
• Scanned copies of DD/BC/BG towards EMD
• Certificates/Documents of the uploaded scanned files
• Certificate of Conformance and markings
• Copy of purchase orders
• EMD
• Bank Guarantee
• Income Tax Clearance Certificate
• Test certificate of manufacturer/Govt. Test House
• DGS&D Rate Contract copy
• SSI/NSIC units registration certificate
• Samples (if asked for)
• Copies of relevant certificate for ISI marked/tested items', '2026-07-11 09:27:39.472', '2026-07-11 09:27:39.472', 'The tender is for the supply of telephone cables, which are not included in the list of eligible products.', false, 'cable,conductors', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102016358', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (822, 13, '14260335', 'supply of thin walled flexible elastomeric cable single core with copper conductors for working voltage above 750 v upto 1.8 kv/3.0 kv as per rdso''s spec. elrs/spec/elc/0019, feb 2018 rev.-4, s ize: 25 sq. mm. colour: red, yellow, blue & black in equal quantity. [ warranty period: 30 months af ter the date of delivery ] ] crw/hrt, ecr', '2026-06-25 00:00:00', 'Nalanda, Bihar, India', 'East Central Railway', '0', '0', '-', NULL, NULL, '1. Udyam Registration Certificate2. Tender Specific Authorization from Manufacturer (as per ANNEXURE-4)3. Manufacturers Test Certificate and OEM Guarantee Certificate4. Bank Guarantee (as per ANNEXURE-5)5. Relevant past performance documents as defined in Para 2.6.1 [A]6. Receipt Notes/Proof of acceptance of material by consignee OR Inspection Certificate with self declaration by the bidder7. Certificate of Tender Specific authorization from the manufacturer8. Manufacturer''s Test and Guarantee certificate9. Bill of Lading/AWB relevant to the consignment10. Commercial invoice of the foreign manufacturer/principals relevant to each consignment11. Current and valid authorization/dealership certificate of foreign manufacturer/principal12. Indian Agent''s Permanent Account Number', '2026-07-11 09:27:47.741', '2026-07-11 09:27:47.741', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101361365', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (823, 13, 'LH265876', 'supply of 16 sq.mm feed through spring clamp terminal connector suitable for used in conductor cross section 16 sq.mm. as per followi ng details:- i) rated voltage:- 800 v ac ii) rated current:- 76a iii) housing material:- polyamide. iv) product function:- feed through. v) wire entry orientation:- top entry. vi) mounting type:- din rail. vii) operated by:- screw driver. viii) rated surge voltage:- 8kv ac similar to con nectwell make model no. csc16t. [ warranty period: 30 months after the date of delivery ] ]', '2026-07-14 00:00:00', 'Lallaguda, Andhra Pradesh, India', 'South Central Railway', '0', '0', '-', NULL, NULL, '1. Past performance report2. Copies of R Notes/CRAC/Proof of acceptance of material by consignee3. Details of M & P, testing facilities, STR & QAP, technical manpower available, UDYAM Registration Certificate for same/similar items (if applicable)4. Tender specific authorization from OEM (if applicable)5. Certificate stating that all statements/documents submitted along with bid are true and factual (Annexure-I)6. Supporting documents duly self-attested/digitally signed for qualifying criteria7. Bid security declaration8. Authorization/dealership certificate issued by OEM (if manufacturer is not quoting directly)9. Performance statement10. Statement of Deviations11. Complete name and address of agents and details of services to be rendered by the agents12. Relevant/valid documents as per Eligibility Criteria13. IRS conditions of contract14. MSE or consortia of MSEs formed by NSIC declaration (if applicable)15. Performance statement (separately attached)16. IRS conditions of contract acknowledgement17. Commercial deviation document18. Technical deviation document19. Latest technical literature/catalogue20. Evidence of valid registration by the competent authority (if applicable)21. Purchase Order (copy)22. GST Jurisdictional Assessing Officers details (Designation, Address & email id)', '2026-07-11 09:27:47.991', '2026-07-11 09:27:47.991', 'The tender brief specifies a connector and does not mention the supply of the listed cables or conductors.', false, 'cable,conductors', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101369840', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (824, 13, 'ET-6279:309400:', 'supply, erection & commissioning of 11 kv lines with mvcc conductor & dismantling of existing open conductor 11 kv lines at ukai tps. (switch yard et-6279)', '2026-06-29 00:00:00', 'Tapi, Gujarat, India', 'Gujarat State Electricity Corporation Limited', '17700', '1418371', '-', NULL, NULL, '1. Tender Fee Payment Receipt/reference receipt2. EMD payment reference receipt3. Authorization letter of the representing company (for technical bid opening)4. Notarized/self-attested copies of original required documents (in pdf format)5. Firm''s details (as per Annexure –3)6. Copy of the un-priced schedule (Annexure – 4)7. Delivery Schedule (Annexure – 5)8. Past experience details (Annexure – 6)9. List of Performance certificates (Annexure – 7)10. List of Type test reports (Annexure – 8)11. Confirmation of GSECL Technical Specification12. Guaranteed Technical Particulars13. AnnexURE – 1014. AnnexURE – 1115. AnnexURE – 1216. AnnexURE – 1317. AnnexURE – 14: Undertaking in regard to Stop Deal / Black List thereof18. AnnexURE – 15: Declaration as manufacturer of tender Item/s19. ANNEXURE – 16: Certificate "A"20. ANNEXURE – 17: Important Instruction21. ANNEXURE – 18: Declaration in respect of Conflict of Interest22. Certificate / document as evidence for experience of having successfully completed similar works/jobs (minimum 01 Job in last seven year period in government / semi government / state electricity board/ corporation body/ public limited company / private limited company)23. Details of minimum tools, tackles and equipment in possession24. Details of P.F. Code no. from appropriate authority25. Average Annual Turnover for the last three years26. Financial standing through latest I.T.C.C Annual report (balance sheet and Profit & Loss Account) of last 3 years27. Certificates/licenses of participating firm in respect of PQC28. Vendor Registration Certificate29. GST Registration Certificate30. PAN Card copy31. Bank details32. Declaration as per Annexure-133. Declaration as per Annexure-234. Declaration of manufacturer for all tendered items (Annexure-15)35. Certificate "A" (Annexure-16)36. Undertaking as per Annexure-1737. Declaration in respect of Conflict of Interest (Annexure-18)38. Labour License39. EMD payment through Cash or online transfer by RTGS/NEFT40. Tender fee (Non-refundable)41. Bank Guarantee (for EMD/Security Deposit)42. PF Certificate (duly signed by DGM / IRO)43. Challan copy44. Permanent Account Number45. HSN/SAC code46. GST no.47. Wage Register (Duly signed by Representative of Ukai TPS) Form No. 1748. Attendance Register49. Bank statement duly stamped by concern bank50. Provident Fund Deposition Form (Original Copy)51. ECR Form (Generated from online RPFC Portal)52. PF Challan with the Sign of competent person53. GST registration certificate54. Contract Labour (Regulation & Abolition) Act, 1970 registration55. Motor vehicle Act, 1988 license (for drivers)56. Electrical contractor license57. Safety shoes58. Safety helmet59. Safety goggles60. Reusable Earplug / Ear muffs61. Chemical suit/Gas tight suit /Fire proximity suit/FR Boiler Suit62. Safety Hand Gloves63. Safety shoes/ Gum Boots with Oil/Chemical/water/heat/Electrical resistance64. Safety Belt (full body hardness with double lanyard & shock absorber) / Rope / Life line / Fall arrestor65. Dust Mask/Respirator with valve (FFP2)66. Chemical Cartridge Respirator with full face mask type67. Trolley mounted Air line respirators with full face mask68. Portable Single gas detector69. Portable Multi gas Detector70. Automatic voltage detector71. Auto darkening welding helmet (EN 379 & EN 175 Level-B) with PAPR as per EN 12941:1998, class TH2 and AS/NZS 171672. PPE under taking73. List of Safety Equipments issued to contractor workers74. Job Safety Analysis (JSA)75. NABL laboratory calibration certificates of electrical / mechanical / Civil / C&I / Environment survey / Chemical etc. measuring / testing equipment''s / instruments76. General Safety Work Permit77. Form No. 2178. Electrical accident form no. A79. List of testing equipment''s (calibrated up dated)80. List of machinery installed for manufacturing81. Annual production capacity (with shift in operation)82. Copy of valid factory license (for manufacturer)83. Registration No. under shops and Estt. Act84. Audited Accounts and financial turnover of Last Three Years85. Performance reports86. Consent letter from their principals to manufacture such items87. Copy of partnership deed / Memorandum of Pvt. or Public limited company''s88. Copy of each order of subsidiary company of GUVNL for each item offered which are executed in last five years89. Copy of each order of subsidiary company of GUVNL and other COMPANY / SEB for each item offered, which is under execution.90. Declaration cum Indemnity Bond (Annexure- "B")91. Valid Electrical contractor License', '2026-07-11 09:27:48.251', '2026-07-11 09:27:48.251', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101372800', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
