INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1108, 17, 'ACE(P&C)/Contract/E-470/TL/66kV/S&E:323009:', 'supply, erection, testing & commissioning of 66kv d/c line on d/c panther tower with al-59 conductor (eq. wt. to acsr panther conductor) from 400kv mevasa substation to 66kv moda substation package 1 from ap-01 to ap-41 having overhead line length 15.49rkm under anjar circle. (only oh portion)', '2026-07-30 18:30:00', 'Vadodara, Gujarat, India', 'Gujarat Energy Transmission Corporation Limited', '11800', '0', '-', NULL, NULL, '• Technical Proposal
• Bid Documents Checklist
• Type Test Certificates for OPGW cable & its associated hardware & fittings
• Completed Data Requirement Sheets
• Quality Assurance Program
• Detailed Project Implementation Plan
• drawings/documents for testing of the system
• Data Requirement sheets
• Sag tension charts
• Bill of Quantity (Drum Schedule & Hardware BOQ)
• Standard documents
• Previous type test report
• Manufacturing Quality Plan
• Test Procedure (Type test & FAT)
• Test report (Type test &FAT)
• Test Schedule
• Transportation & handling procedure
• Numbering, Marking, labeling document
• System Functional Description Document
• Type test documents (Procedures & Reports)
• Factory Acceptance Test Documents (Procedures & Reports)
• Site Acceptance Test Documents (Procedures & Reports)
• drawings
• Proforma invoice(s) for advance payment
• Advance Bank Guarantee for [{110% (one hundred ten percent) of the amount of Advance} Plus {amount of GST reimbursable on Advance as per the Proforma invoice, if applicable}]
• Performance Securities in line with GCC Clause 40.0 including its sub-clause
• Declaration stating that the Contractor has opted for interest bearing mobilization advance or has opted not to take interest bearing initial mobilization advance
• Undertaking for Liquidated Damages (LD) for Delay
• Undertaking for utilizing existing Bank Guarantees or Other Securities
• Undertaking to extend the validity of Bank Guarantees or securities
• Undertaking confirming the proper execution of the contract in good faith
• Undertaking regarding conflict of interest
• Undertaking regarding use of ''Call Before u Dig'' (CBuD) mobile application
• Quality Assurance Plan (QAP)
• Field Quality Plan (FQP)
• Type test reports for the offered item
• Chemical Composition Test
• Magnetic Particle Inspection test on forging
• Cost of logistics will be borne by GETCO
• Technical deviations
• Samples
• Proforma invoice
• Advance Bank Guarantee
• Vendor Registration No.
• CA certificate to be attached for MAAT, Liquid Assets and Net-worth
• Undertaking in respect of reference to NCLT under Insolvency & Bankruptcy Code
• Supply/Order executed details for offered items with name of purchaser, date and location
• Performance certificate for satisfactory operation/working', '2026-07-13 07:02:02.025', '2026-07-13 07:19:59.256', 'The tender involves the supply of AL-59 conductors, which is an eligible product, but it also includes erection, testing, and commissioning, which may disqualify it unless the supply aspect is clearly the primary focus.', false, 'cable,conductors', NULL, '107484563', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102203076', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
