INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (856, 13, '64037/Ad BIV A/2023/UOK', 'supply, installation, testing and commissioning of 2 number of 2 ton air conditioners for the department of statistics, university of kerala supply , installation, testing and commissioning of fully charged(top-up as per site requirement)  2.0tr, bee five star rated, high wall split air conditioning unit(suitable for commercial/industrial use) fitted with variable frequency drive inverter compressor(dual inverter or equivalent) operating on either r32/r290 refrigerants, complete with indoor and out door units comprising of blowers, motors, bluefin/gold fin copper cooling tube coil and bluefin/gold fin copper condenser tube coil. the machine should be high wall mounter capable of dust filtering, cooling, dehumidifying, air circulating . the package shall have microprocessor control with cordless remote, refrigerant, electric cable of isi mark interconnected control cable (2.5sq.mm or suitable size) from indoor to outdoor units, , copper pipe and thermal insulation up to 3.5 m with 13mm nitrile rubber insulation, with uv proofing, heavy duty pvc drain pipe, and unit should be suitable for long copper pipe length more than 20 mtr (distance between outdoor & unit) as required with two year on-site warranty and free service in every three months during warranty period, minimum 5 year compressor warranty, p supply and installation soft drawn bright annealed copper pipes of 0.8mm thickness(suction and discharge) covered with sleeve type insulation of oem approved make insulation of minimum 10 mm thick completely wrapped with monsoon tape shall be fixed on walls with aluminium straps with necessary brazing, pressure testing suitable for 2tr machines, supply and installation of powder coated/stove enamelled metallic mount for wall mounting of out door unit of air conditioner with required number of anchor bolts, vibration isolators and non slip foundation bolts of suitable size of odu supply of 5kva volage stabiliser for split ac unit with voltage range of 140-280 v stabiliser with low and high voltage cut off, intelligent time delay, thermal overload protection, micro-controlled circuitry, digital display, fire-retardant abs plastic body,wall mountable cabinet design with 3 months replacement warranty, supply and installation of drain pipe for split air conditioner of pvc 15kg/me density of size 20mm, supplying and drawing following sizes of frls pvc insulated copper conductor, single core cable in the existing surface / recessed steel/ pvc conduit as required.4 x 2.5 sq. mm', '2026-06-28 00:00:00', 'Thiruvananthapuram, Kerala, India', 'University Of Kerala', '472', '1500', '-', NULL, NULL, NULL, '2026-07-11 09:27:56.545', '2026-07-11 09:27:56.545', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101629549', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
