INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (863, 13, '40261004', 'supply of cord flexible twin core unsheathed pvc insulated cable, size 24/0.20 mm (0.75 s qmm), having copper conductor, for rated voltages up to and including 1100 v grade, con forming to is:694-2010 with amendement no 1 to 4 [ warranty period: 30 months after the date o f delivery ] [quantity tolerance (+/-): 5 %age , item category : normal , total po value variation permitted: max 8 lacs ] ] carriage stores depot ajmer,', '2026-07-22 00:00:00', 'Ajmer, Rajasthan, India', 'North Western Railway', '0', '0', '-', NULL, NULL, '1. E-bids2. Declaration signed digitally3. Techno-Commercial offer Form4. Financial offer Form5. Scanned copy of all the documents needed as per Annexures6. Certificate stating that all statements/ documents submitted along with bid are true and factual (Annexure-IX)7. Online certificate/declaration available in tender NIT mentioned points which cover all paras of Annexure-IX8. Udyam registration certificate9. Udyog Aadhar Memorandum10. Current & valid registration certificate along with offer (for MSEs)11. Certificate from the statutory auditor or cost auditor or practicing Cost accountant giving the percentage of local content (for contracts above INR 10 Crores)12. UDIN mentioned in certificate13. Tender Drawing No./Part No./Specification (if quoted)14. Copies of drawings/specifications/catalogue15. Authorization letter from manufacturer on their letterhead (Annexure-V)16. NSIC registration certificate17. OEM certificate for country of origin (for items sold by reseller)18. Copy of EMD payment19. Bid securing declaration20. MSE certificate containing status of ownership by SC/ST or women21. Tenderer''s offer for AMC (if applicable)22. Warranty Bank Guarantee (Annexure-VII)23. National Electronic Funds Transfer (NEFT) Mandate Form (Annexure VIII)24. Certificate from Bank certifying correctness of Bank Account details25. Copy of crossed cheque', '2026-07-11 09:27:58.313', '2026-07-11 09:27:58.313', 'The tender brief specifies a supply of flexible twin core unsheathed PVC insulated cables, which is not among the exact products listed.', false, 'cable,conductors', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101679247', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (864, 13, '90261046', 'supply of cable pvc insulated flexible twin twisted copper conductor suitable for 1100 v grade co nfirming to is: 694/2010 or latest with latest amendment size: 16/0.20 mm (0.50 q.mm) , colour of ins ulation: red and black. [ warranty period: 30 months after the date of delivery ] ]', '2026-07-02 00:00:00', 'Bhubaneswar, Orissa, India', 'East Coast Railway', '0', '0', '-', NULL, NULL, '1. copy of purchase order2. receipted challan3. inspection certificate4. performance statement/P.O. copy/ receipt note5. OEM/dealership certificate6. GSTIN registration no7. Documentary evidence of GST payment8. Registration with the competent Authority for country specific procurement9. Deviation statement', '2026-07-11 09:27:58.565', '2026-07-11 09:27:58.565', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101683786', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1271, 18, 'NSU6E32H', 'installation of rack, cable tray, enclosure box, cable routing, labelling and connectivity with various equipment and supply of installation material and accessories at project sites.', '2026-07-14 18:30:00', 'Bangalore, Karnataka, India', 'ITI Limited', '0', '100000', '-', NULL, NULL, '• Tender fee submission proof
• EMD submission proof
• Declaration of bidders
• MSME registration certificate
• Power of Attorney of authorized signatory (on stamp paper duly notarized)
• EPF registration certificate
• GST registration certificate
• Audited financial statements for the last three years (certified by Chartered Accountant with registration number)
• Organization set up of the company
• Work completion certificates during the last three years
• Details of ongoing works
• Signed Integrity Pact
• Any Litigation History
• All the pages of tender documents signed
• Signed Pre-contract Integrity Pact and non-disclosure agreement
• Undertaking that the bidder has not been blacklisted/debarred
• Compliance to no variance/deviation in bid
• Undertaking for non-engagement of child labour
• Work experience certificate (as per Annexure VIII)
• Bidder''s Profile (as per Annexure VI)
• Declaration regarding work experience organization (as per Annexure VII)
• PAN Number
• GST Registration certificate
• Valid Digital Signature Certificates (Class III with signing and Encryption key)
• Income Tax Return for the last three financial years', '2026-07-13 07:02:42.993', '2026-07-13 07:28:04.522', 'The tender is focused on installation and related services without explicitly mentioning the supply of any eligible power cables or conductors.', false, 'cable,conductors', NULL, '5000000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102118870', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (717, 13, '2026_MES_771419_1', 'corrigendum : servicing / maint / repair / replacement of busbar chambers lt ug cables, lt panels, junction boxes, lt oh line, servo voltage stabilizer and allied services and repair / maint of ht electric supply at mh jodhpur under ge (army) no. 02', '2026-07-09 00:00:00', 'Jodhpur, Rajasthan, India', 'Military Engineer Services', '500', '66000', '-', NULL, NULL, '1. Application for tender on Firm''s letterhead2. Enlistment letter issued by the Registering Authority duly renewed for cycle period in vogue3. Scanned copy of DD /Bankers Cheque toward cost of tender and EMD instrument in case SSD bond is not signed at the time of registration4. Details of works in hand showing names of work, names of Accepting Officers, Contract amounts, dates of commencement and completion (stipulated) and progress as on bid submission date5. Any other document required as described in this Appendix ''A''6. Scanned copy of DD/ Bankers cheque toward cost of tender and Earnest Money Deposit (EMD) instrument7. Copy of police verification Report/ Police Clearance Certificate/ Character Certificate from the Police Authority of the area where the registered office of the firm is located/ notarized copy of valid passport of Proprietor/each Partner/each Director8. All documents required for enlistment in MES for the class mentioned in Para 8 (b) above as per Para 1.5 of Section I of MES Manual on Contractor 20209. Details of works being executed in MES, if any10. Any other document required as described in this Appendix11. Copy of agreement with agency having valid Electrical License12. Agency''s Electrical License13. Supervisor Certificate of Competency issued by concerned State Government/Union Territory14. Permit issued by concerned State Government/Union Territory for workers/tradesmen15. Manufacturer''s test certificate for materials16. Material/item test certificates (duly cross linked in the purchase voucher)17. Provident Fund (PF) code number for coverage of building and construction workers (BACW) in the schemes framed under Employee''s Provident Fund & Miscellaneous Provisions (EPF & MP) Act 195218. GST registration certificate19. Undertaking stating if they have appealed to E-in-C Br and current status of their appeal', '2026-07-11 09:27:20.72', '2026-07-11 09:27:20.72', 'The tender brief pertains to servicing, maintenance, and repair, not the supply of specified cables or conductors.', false, 'cable,conductors,date', NULL, '3300000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101236534', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
