INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (872, 13, '02265060A', 'design, manufacture, supply of one (01) number of 10 tonnes electric overhead travelling crane along with lifting magnet suitable for scrap handling and all accessories conforming attached leadin g parameters. ii) installation, commissioning of one (01) number of 10 tonnes electric overhead travelling c rane. iii)removal of existing dsl conductor system and supply, installation and commissioning of new dow n shop lead conductor system of 336 meter. iv) spares (as indicated in leading parameters). v) training of s taff. [ warranty period: 24 months after the date of delivery ] ] sse/mech/maintenance/ melt', '2026-06-25 00:00:00', 'Saran, Bihar, India', 'Rail Wheel Plant', '0', '764640', '-', NULL, NULL, NULL, '2026-07-11 09:28:01.13', '2026-07-11 09:28:01.13', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '100893762', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1273, 18, 'DMA/2026-27/WS/WORK_INDENT60755', 'suppylying of 20 hp submersible motor pumps, flat cable, g.i pipes, out door boxes and other water supply borwell materials in cmc hosakote limits.', '2026-07-26 18:30:00', 'Bangalore, Karnataka, India', 'Department Of Municipal Administration', '1180', '94000', '-', NULL, NULL, '• Copy of Constitution or legal status of Tenderer
• Place of Registration
• Total value of civil engineering construction works executed and payments received in the last five years (2021-22 to 2025-26)
• Work performed as Prime Contractor (in the same name) on works of similar nature over during the five years specified in 1.2 above
• Quantities of work executed as prime contractor (in the same name) during the last five years specified in 1.2 above
• Information on works for which Tenders have been submitted and works which are yet to be completed as on the date of this Tender
• List of equipment considered essential for successfully carrying out the works
• Reports on the financial standing of the tenderer, such as profit and loss statements and auditor’s reports for the last five years
• Qualification and experience of the key technical and management personnel in permanent employment with the tenderer and those that are proposed to be deployed on this contract
• Name, address, and telephone, telex, and fax numbers of the Tenderers'' bankers
• Evidence of access to financial resources to meet the qualification requirement specified in ITT Clause 3.3 (b): Cash in hand, Letter of Credit etc.
• Certificate from the Banker in the suggested format for financial standing
• Proposals for subcontracting components of works amounting to more than 20% of the contract price
• Information on litigations in which the Tenderer is involved
• Tender (in the format indicated in section 3)
• Earnest Money Deposit & tender Processing fee; online payment through E-Procurement platform
• Qualification Information as per section 1.1 to 1.4 including Performa uploaded separately and to comply the task created in the e-Procurement Portal under General terms and Conditions and Technical parameters and Documents required from Tenderer
• Priced Bill of Quantities (Section 8)
• Turn over certificate, duly certified by chartered Accountant along with UDIN No.
• Work done certificate issued by officer not below the executive engineer
• GST certificate
• Current income-tax clearance certificate
• Scan copy of the original challan for EMD and tender processing fee', '2026-07-13 07:02:43.456', '2026-07-13 07:28:13.021', 'The tender is for the supply of submersible motor pumps and general materials, but does not explicitly mention any of the eligible power cables or conductors listed.', false, 'cable,conductors', NULL, '4700000', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102213517', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1281, 18, 'BSD/UG/2026-27/N-Proc./PR- 229806:322028:', 'arc for erection of ug cable and maintenance work at laying and maintenance of ug 11 kv xlpe cable for si,skjy & nd schemes and maintenance only, including supply & erection of cable joint kit as and when required basis at borsad rural s dn & any other sdn.of borsad division area. of the all scheme for borsad rural & any other sub division under borsad do', '2026-07-28 18:30:00', 'Anand, Gujarat, India', 'Madhya Gujarat Vij Company Limited', '1770', '0', '-', NULL, NULL, '• E.M.D. technical bid
• Online payment receipt of Tender Fee
• Online payment receipt of EMD
• Valid exemption certificates (duly notarized)
• UDYAM REGISTRATION CERTIFICATE
• Small Scale Industries of Gujarat State registration certificate
• NSIC registration certificates
• CSPO registration certificates
• DGS&D registration certificates
• Electrical contractor''s license
• Work order copies
• Experience certificate
• Certificate of work experience
• Digital map of underground network with GPS instrument
• Work order copy
• Notarized copy of SSI certificate
• Notarized copy of applicable valid acknowledgement of memorandum filed by Small, cottage and tiny industrial units with the District Industrial Centre (DIC) of Gujarat State
• Notarized copy of subsequent registration certificate of CSPO/NSIC/DGS&D
• Certificate of work experience issued by Engineer in charge
• Average Annual financial turnover certificate of Chartered Accountant
• Copy of valid E. P. F. Registration
• Copy of valid GST Registration Certificate
• Copy of valid PAN card
• Copy of valid Labour Insurance Policy
• Latest bank solvency certificate
• Test Certificate for materials
• Identity cards as prescribed under the factories Act with photo affixed
• Contractor''s affidavit regarding conflict of interest
• Work order for similar items executed
• Bank Guarantee for EMD
• Bank Guarantee for Performance Guarantee
• Bank Guarantee for Warranty Period
• Indemnity Bond
• Workmen''s Compensation Fund and Employers Liability Insurance
• Any other document as specified in the tender', '2026-07-13 07:02:45.487', '2026-07-13 07:28:24.38', 'The tender brief primarily focuses on erection and maintenance work, with only a mention of supply related to cable joint kits, and does not explicitly involve the supply of eligible products listed.', false, 'cable,conductors', NULL, '3998848', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102123549', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (723, 13, '2026_MIL_281785_1', 'maintenance of ht power supply system including switchgear panels, vcbs, ocbs, transformers, ab switches, ht underground cables, ht overhead line etc. inside factory area, at o.f.bhandara', '2026-07-06 00:00:00', 'Bhandara, Maharashtra, India', 'Ordnance Factory', '0', '45500', '-', NULL, NULL, '1. Original copies of EPF2. PAN card3. Turn Over4. EMD5. GST6. Registration certificate7. Experience/work completion certificate8. Class III Digital Signature Certificate (DSC)9. Work Completion certificates against similar type of Contracts/ Works10. Electrical contractor licence copy11. Tender Acceptance Letter in prescribed format12. Cancelled Cheque (compulsory)13. Bank Verification (Certified by Bank with Signature & Seal of Bank Official)14. MSME Details (Self attested copies)15. MSEME Minority Indicator16. Group Accidental Insurance', '2026-07-11 09:27:22.236', '2026-07-11 09:27:22.236', NULL, NULL, 'cable,conductors,date', NULL, '2272877', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101619508', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
