INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1506, 28, '945132', 'supply of 4core 185sqmm xlpe insulated 1100 volts aluminum power cables', '2026-07-16 18:30:00', 'india', 'andhra pradesh power generation corporation limited', '0', '0', NULL, NULL, '0', NULL, '2026-07-13 08:05:53.394', '2026-07-13 08:17:00.248', 'The tender explicitly involves the supply of XLPE Power Cables, which is an eligible product.', true, NULL, NULL, '0', NULL, 'INR', 'Download Link', NULL, NULL, '09-07-2026', 'wire and cable', NULL, NULL, '98268170', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1286, 18, '03 of 2026-27:322230:', 'providing ,supplying & fitting motor pump and related work & columns and cables at the headworks of jooth panchayat waterworks at-vijapur nagarpalika,vijapur', '2026-07-17 18:30:00', 'Mehsana, Gujarat, India', 'Municipal Corporation', '1770', '36520', '-', NULL, NULL, '• PAN Card Copy
• P.F. Registration Number Copy
• Last three (3) Month PF Approved Challan Copy
• G.S.T. Registration Number Copy
• Last three (3) Month GST Approved Challan Copy
• Last 3 years Income tax return files Copy
• Valid Bid Security / EMD Exemption Certificate (if applicable)
• Solvency Certificate (20% value of estimated cost put to tender Current Calendar Year)
• T.P.I charge @ 0.45% of Bill Amount Undertaking
• Similar work Contractor registration with “E1" Class and above
• Similar work experience of One years
• Three completed Similar works costing not less than the amount equal to 40% of the estimate cost
• Two completed Similar works costing not less than the amount equal to 50% of the estimated cost
• One completed Similar work costing not less than the amount equal to 80% of the estimated cost
• JV Agreement (if applicable)
• Evidence of access to financial resources (undertaking that he has access to, or has available, liquid assets (aggregate of working capital, cash in hand and uncommitted bank guarantees) and / or credit facilities up to 25 percent of the value of the contract / contracts applied)
• Audited balance sheets for the last five years
• Information on Litigation history
• Affidavit
• Undertaking
• Checklist / Qualification Document / Tender Document
• Technical Bid
• Financial Bid
• Form of Bid
• Priced Bill of Quantities
• Bid Security
• Registration Certificate of Appropriate Class and Category of Approved Contractors (if required)
• Digitally signed Bid
• Valid Digital Certificate
• Copies of certificates on possession of valid license for executing water supply/ sanitary work/ building electrification works
• Biographical data of key personnel
• Statement of compliance under the requirements of Sub Clause 3.2 of the instruction to Bidders
• Proposed work method and schedule
• Programme
• Additional Information required to fulfill the requirements of Clause 4 of the Instructions to the Bidders', '2026-07-13 07:02:46.631', '2026-07-13 07:28:35.42', 'The tender is focused on providing, supplying, and fitting a motor pump and related work, but does not explicitly mention the supply of any eligible cables or conductors.', false, 'cable,conductors', NULL, '3651612', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102155023', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (880, 13, '35265274', 'supply of 2 conductor through terminal block of size 16 sq mm lateral making for din rail 35x15 and 35x75 mm in grey colour with operating slots and integrated end plate to wago cat no 283-101. acceptabl e makes- wago, weid-muller, phoenix, connectwell only as per sr. no. 73,74,75 of rdso letter no. el/7.1.1 08/mssbc dated 17.09.2021 [ warranty period: 30 months after the date of delivery ] ]', '2026-07-12 00:00:00', 'Jodhpur, Rajasthan, India', 'North Western Railway', '0', '0', '-', NULL, NULL, '1. Authorization Letter from OEM2. MSE Certificate3. UDYAM Registration Certificate4. Udyog Aadhar Memorandum5. Bid Securing Declaration6. Digital Signature Certificate7. Registration on Indian Railways E Procurement (IREPS) website8. Annexure V: Proforma for Authority from Manufacturers9. Annexure VI: Proforma of Online/Offline Bank Guarantee for Contract Performance Guarantee Bond10. Annexure VII: Proforma for Warranty Guarantee Bond11. Annexure VIII: National Electronic Funds Transfer (NEFT) Mandate Form12. Annexure IX: Format for Certificate to be Submitted/ Uploaded by Tenderer', '2026-07-11 09:28:03.145', '2026-07-11 09:28:03.145', 'The tender brief specifies a conductor assembly for terminal blocks rather than the supply of power or signaling cables or conductors listed in the specified products.', false, 'cable', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101335496', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1288, 18, '64/EE(E)-II-Hyd/2026-67', 'supply, installation, testing and commissioning of 250 kva dg set along with 4 wheeled trolley and copper cables at hcu, gachibowli, hyderabad. subwork/packages: sitc of 250 kva dg set along with 4 wheeled trolley', '2026-07-15 18:30:00', 'Hyderabad, Telangana, India', 'Central Public Works Department', '0', '69585', '-', NULL, NULL, '• Treasury Challan /Demand Draft/Pay order or Banker''s Cheque /Deposit at Call Receipt/FDR / Bank Guarantee of any Scheduled Bank against EMD
• Enlistment Order of the Contractor
• Bidder to upload receipt of deposition of EMD
• ERP Training Certificate
• Telangana GST registration certificate, if already obtained by the bidder
• Undertaking for GST registration (if not registered in the state where the work is to be taken up)
• Verifiable completion certificates of the work
• Registration/approval documents as the case may be, duly attested by the applicant
• Self attested GST registration documents in respect of the associated agencies
• MOU signed with the associated contractors
• Copy of Enlistment Order / Certificate of work experience
• Other documents as specified in the press notice
• Type Approval certificate (for DG Set)
• Certificate of conformity of production (for DG Set)
• Certificate of Type Approval (for DG Set, if capacity > 200 KVA)
• Certificate of conformity of production (for DG Set, if capacity > 200 KVA)
• Mosses of materials of local suppliers
• Certificate for all items except for sundry items
• Relevant IS or any other International code documentation
• Proof of applying for obtaining labour licenses
• Proof of applying for registration with EPFO, ESIC and BOCW Welfare Board
• Proof of applying for provident fund code No
• Copy of applicable license/ registrations
• Proof of applying for obtaining labour licenses
• Proof of applying for registration with EPFO, ESIC and BOCW Welfare Board
• Programme Chart (Time and Progress)
• Copy of applicable license/ registrations
• Valid Electrical Licence
• Annual Pre-qualification Order
• Work experience certificates of each agency for each component of E&M work', '2026-07-13 07:02:47.125', '2026-07-13 07:28:38.092', 'The tender brief focuses on the supply, installation, testing, and commissioning of a DG set and mentions copper cables, but does not explicitly specify the supply of any eligible products listed.', false, 'cable,conductors', NULL, '3479273', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102105216', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
