INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (763, 13, '2026_MDL_99696_1', 'corrigendum : supply of ebxl cables', '2026-07-16 00:00:00', 'Mumbai, Maharashtra, India', 'Mazagon Dock Shipbuilders Limited', '0', '0', '-', NULL, NULL, '• Company Profile
• Copy of valid registration certificate for MSE/NSIC
• Partnership Deed and Registration Certificate issued by Registrar of Companies
• Certificate of Incorporation issued by Registrar of Companies
• Valid Certificates issued by Govt. Undertaking/Defence PSUs/DGQA/Indian Navy/Indian Coast Guards
• Factory License/Municipal Shop''s and Establishment Certificate
• Registration Certificate from Labour Commissioner
• GST Registration No. with photocopy of valid registration certificate
• Copy of PAN Card
• Copies of I.T. Return Paid Acknowledgements for the preceding 3 Assessment years
• Name of the Bankers with address, Telephone number and FAX No., NEFT/RTGS/IFCS & MICR details
• Type of Account (SB/Current/Cash Credit/Overdraft)
• Names and address of Associated/ Sister Manufacturing / Sub Contracting/Trading concerns and list of their directors/partners/proprietor
• List of Plant & Machineries owned
• Godown / Warehouse Area address with Phone Number, Rent Receipt and valuation of stock
• Transport Facilities for Delivery and collection of Goods
• Names and designation of officials who will deal and interact with Defence Public Sector Shipyards officials
• Confirmation of position to supply items duly approved by DGQA / Lloyds / ABS / IRS / DNV / other Third Party Agencies
• Details of any Banned / Black Listed status by any Govt. Undertaking
• EOI Acceptance Format
• GCC Acceptance Format
• Declaration by bidder for Restrictions under rule 144(xi) of general financial rules GFRs, (2017)
• RTGS/ NEFT - Mandate Authorization Form
• Declaration of Local Content
• Bid Security Declaration
• Scanned copy of the Integrity Pact duly signed by bidder
• Copy of Purchase Orders (PO)
• Work Completion Certificates OR any other document(s) establishing successful execution of PO/Contract
• Contract copy along with Invoice(s) with self-certification
• Contract copy along with Execution certificate by client with contract value
• Contract copy along with Third Party Inspection release note with Delivery challan with purchaser stamp
• Start-ups certificate as recognized by Department of Industrial Policy and Promotion (DIPP)
• Undertaking regarding not being under tender holidays / adverse ratings
• Self-certification by Chief Financial Officer or Other legally responsible person nominated in writing by the Chief Executive or Senior Member / Person with Management Responsibility of Corporation / Partnership / Individual
• Certificate from statutory auditor or cost auditor of the company (in case of companies) or from a practicing cost accountant or practicing charted accountant (in respect of supplier other than companies) giving the percentage of local content
• Compliance Certificate w.r.t. Land Border Clause', '2026-07-11 09:27:32.563', '2026-07-11 09:27:32.563', 'The tender brief mentions ''ebxl cables,'' which are not listed among the eligible products.', false, 'cable', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101737306', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
