INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1107, 17, 'PGVCL/Tech/SI/2026-27/02:316163:', 'site survey, designing, engineering, procurement, supply, loading, transportation, unloading, insurance, delivery at site, handling, storage, installation, testing, commissioning including documentation of all items/material required to complete works for turnkey based contract for 11 kv al-59 acs medium voltage covered conductor (mvcc) with its accessories with pole in feeder of dhoraji division of rajkot rural circle of pgvcl under si scheme.', '2026-07-14 18:30:00', 'Rajkot, Gujarat, India', 'Paschim Gujarat Vij Company Limited', '17700', '0', '-', NULL, NULL, '1. Detailed comprehensive Quality Assurance Mechanism (QAM) plan/Guaranteed Technical Particulars2. Manufacturing Quality Plan (MQP)3. Field Quality Plan (FQP)/Approved Drawings/Data Sheets4. Type test report of the Material5. Pre-dispatch inspection reports6. Type tests conducted in an accredited laboratory (accredited based on ISO/IEC Guide 25/17025 or EN 45001 by the national accreditation body of the country where laboratory is located) or witnessed by the representative(s) of Employer or Utility.7. Test reports conducted within last 5 (five) years prior to the date of bid opening.8. Contractor''s Test certificate9. Authorization Letter10. Safety Plan11. Documented pre-commissioning test checklist signed by the quality engineer of the turnkey Contractor and countersigned by Employer''s representative.12. Proof of registration as an approved vendor in the DISCOMs of GUVNL/GETCO.13. Bank Guarantees (Bid Security, Advance Payment Security, Performance Security)14. Insurance Policies (Marine Cargo Policy/Transit Insurance Policy, Erection All Risk Policy/Contractor All Risk Policy, Third Party Liability cover, Contractor''s Plant and Machinery (CPM) Insurance, Workmen Compensation Policy)15. Certificate of Financial Parameters for QR16. Power of Attorney for Joint Venture17. Undertaking by the Joint Venture Partners18. Any other documents as specified in the Bidding Documents.', '2026-07-13 07:02:01.644', '2026-07-13 07:02:01.644', 'The tender brief specifically mentions the supply of ''11 kv al-59 acs medium voltage covered conductor (mvcc) with its accessories,'' which directly relates to the listed products.', true, 'cable,conductors', NULL, '112448342', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101651562', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
