INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1101, 17, 'KPTCL/2026-27/SS/WORK_INDENT3690', 'establishing 2x20mva, 110/11kv sub-station at shivoor and construction of 110kv lilo line using lynx conductor from existing 110kv afzalpur-karajagi sc line to the proposed 110/11kv sub-station at shivoor for a distance of about 9.982kms in afzalpur taluk, kalaburagi district on partial turnkey basis including supply of all matching materials/ equipments (excluding supply 11kv switchgear) and erection (including dismantling and civil works) of all materials/ equipment, testing and commissioning', '2026-08-05 18:30:00', 'Bangalore, Karnataka, India', 'Karnataka Power Transmission Corporation Limited', '7500', '2183000', '-', NULL, NULL, NULL, '2026-07-13 07:01:59.499', '2026-07-13 07:19:48.296', 'The tender brief is primarily for installation and construction work, even though it mentions supplying materials; it does not explicitly specify the supply of eligible products listed.', false, 'cable,conductors', NULL, '218262904.23', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102087609', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1103, 17, 'ACE(P&C)/Contracts/E-472/TL/66kV/S&E:313819:', 'supply, erection, testing & commissioning of lilo to 400kv mevasa from 66kv s/c pragapar rapar line on d/c panther tower with al-59 conductor (eq. wt. to acsr panther conductor) having overhead line length 21.32rkm under anjar circle. (only oh portion)', '2026-07-15 18:30:00', 'Vadodara, Gujarat, India', 'Gujarat Energy Transmission Corporation Limited', '11800', '375000', '-', NULL, NULL, '1. Tender Papers / Specifications2. Amendment-I of Part-I Tender Specification3. General Conditions of Contract (GCC)4. Special Conditions of Contract (SCC)5. Technical Specifications / Bidding Documents6. Detailed PERT Network/ Bar chart7. Schedule-2A (L2 Schedule)8. Schedule-21 (Option for Initial Advance)9. Annexure-IV (Under taking regarding NCLT)10. Notarized undertaking regarding NCLT status11. Supply/Order executed details for offered items with name of purchaser, date and location12. Performance certificate for satisfactory operation/working13. Annexure-1 (Bank Guarantee Form for Advance Payment)14. Annexure-III (SCHEDULED-21)15. Schedule-03 - Financial capability16. Schedule-06 – Confirmation of Details of Bidder17. Annexure – 1 – Details of Firm18. Annexure – 2 – Details of Experience19. Annexure – 3 – List of Performance Certificate20. Schedule-16 – Confirmation of attachment21. Annexure - X22. Type Test Certificates for OPGW cable & its associated hardware & fittings23. Completed Data Requirement Sheets24. Quality Assurance Program25. Detailed Project Implementation Plan26. Type test reports from NABL accredited/Government Laboratory (not older than five years)27. Type test reports from NABL accredited/Government Laboratory for AL 59 Panther conductor (not older than seven years from date of opening of bid)28. Routine test certificates of all the bought out items, accessories etc.29. Detailed drawings in triplicate for the offered insulators30. Manufacturer''s Quality Assurance Plan (QAP)31. Field Quality Plan (FQP)32. Drawings in AutoCAD format and manuals in PDF format33. Hard copies of drawings as per specification34. Test certificates for material composition35. GTP (Guaranteed Technical Particulars) for accessories36. GTP (Guaranteed Technical Particulars) for AL59 Panther conductor37. GTP (Guaranteed Technical Particulars) for OPGW cable38. GTP (Guaranteed Technical Particulars) for Silicon Rubber Housed Composite Insulators39. Pre-installation test report for OPGW & Approach Cable (Drum Test)40. Splice Test Report for OPGW (1310 nm)41. Splice Test Report for OPGW (1550 nm)42. Splice Test Report for Splicing OPGW & Approach Cable (1310 nm)43. Splice Test Report for Splicing OPGW & Approach Cable (1550 nm)44. FO Cable End to End Test using OTDR (1310 nm)45. FO Cable End to End Test using OTDR (1550 nm)46. FO Cable End to End Test using Power Meter (1310 nm)47. FO Cable End to End Test using Power Meter (1550 nm)48. GST Registration Certificate49. PF Registration Certificate50. Valid Electrical Contract License51. Certificate of Net Worth for last financial year (must be positive)52. CA Certificate with valid UDIN Number for MAAT, LA and Net-worth53. Audited Balance Sheet and Profit & Loss account for the preceding five financial years54. Undertaking regarding NCLT under Insolvency & Bankruptcy Code (as per Annexure-IV)55. Bidder''s Minimum Average Annual Turnover (MAAT) certificate56. Last Financial Year Liquid Assets certificate57. E.M.D. BANK GUARANTEE FORMAT58. FORM OF BANKER''S UNDERTAKING (Combined Performance Guarantee)59. Tender Fee (Non-refundable)60. EMD (Earnest Money Deposit)61. Integrity Pact62. Any other documents/certificates as per the tender document.', '2026-07-13 07:02:00.26', '2026-07-13 07:19:54.455', 'The tender is for erection, testing, and commissioning only, and while it mentions AL-59 conductor, it does not explicitly list its supply.', false, 'cable,conductors', NULL, '167880733', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101301413', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
