INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (741, 13, '15260122', 'supply of pvc insulated cable for railway signalling heavy duty under ground unscreened armoured with galvanised round steel wire and the conductors of plain solid annealed high conductivity copper each with nominal cross section area of 1.5 sqmm conforming to specn no .irs-s-63/2014 (rev 4.0) or latest. size 24 core x 1.5 sqmm. [ warranty period: 30 months after the date of delivery ] [quantity tolerance (+/-): 2 %age , item category : special (signaling cables) , total po value variatio n permitted: not applicable ] ] amm/gsd/goc, sr', '2026-07-14 00:00:00', 'Tiruchirappalli, Tamil Nadu, India', 'Southern Railway', '0', '160360', '-', NULL, NULL, '1. Scanned copy of approval letter from RDSO/ CORE/ PUs etc. indicating current validity along with approval of their QAP etc, wherever restricted procurement from approved sources.2. Scanned Copy of Permanent Account Number (PAN) from Income Tax Department3. Tender specific authorization letter from OEM / principal with required undertaking as per eligibility criteria from OEM as well as dealer.4. Scanned copy of NEFT mandate for payment purpose.5. Clause wise compliance to specification / Tender Conditions wherever required.6. Deviation Statement from technical specification & commercial terms and conditions if any.7. Proforma for Equipment and Quality Control8. Proforma for Authority from Manufacturers9. Proforma for Performance Statement10. Proforma of Bank Guarantee for Contract Performance Guarantee Bond11. Proforma of Bank Guarantee for Security Deposit12. Proforma for Document of Authorization for Payment Through Letter of Credit13. No Claims Certificate to be given by Contractor14. Bid Securing Declaration to be Signed by Bidders Availing Exemption from Submission of EMD15. Competent Authority and Procedure for Registration (Bidders from Land Border Countries)16. Declaration by Bidders from Land Border Countries17. Digitization of Warranty Management System', '2026-07-11 09:27:26.802', '2026-07-11 09:27:26.802', 'The tender brief specifies the supply of PVC insulated cable and conductors which match the listed categories of signalling cables.', true, 'cable,conductors', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101021069', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (742, 13, '20261133', 'supply of supply and commissioning of igbt based 3-phase drive propulsion equipment with physical medium i.e. esd/ emd/ ofg for multi - functional vehicle bus (mvb) as per iec 61375, terminal bracket, bus bar link and cu braid required for connection between mai n transformer and traction converter, auxiliary converter, interfacing connectors, c ables and cable loom required for connection from vcu1/2 to sb1/2 panel. as per spec. no. i) rdso/2008/ el/spec/0071, rev. 5 for igbt based 3-phase drive propulsion equipment, ii ) clw/es/3/0458 alt. e for cont rol cables, iii) clw/es/3/0459 alt. c for screened cable, iv) clw/es/3/0124 alt. p. in addition to above description, the propulsion system should als o comply requirement mentioned in "schedule of requirement" (sor) doc no. plw/el/prop ulsion system/sor/002 rev. 02 with annexure a, b , c , d & e [sept-25]., copy attached with tender documents. annual maintenance for three (03) years will be as per comprehensi ve annual maintenance specification no. clw/amc/c-d&d/01 issued in march 2016. [ warra nty period: 72 months after the date of delivery ] ]', '2026-07-06 00:00:00', 'Patiala, Punjab, India', 'Patiala Locomotive Works', '0', '5000000', '-', NULL, NULL, '1. Authorization letter from OEM (Original Manufacturer)2. Performance statement for supplies made against Purchase Orders placed by PLW or any other unit of Indian Railways for supply of same/similar item in preceding three years3. Purchase Orders placed by PLW or any other unit of Indian Railways4. Inspection Certificates5. Receipt Notes6. User-feedback7. Details of M & P (Machinery and Plant)8. Testing facilities9. QAP (Quality assurance Plan)10. Technical manpower available11. Letter of latest approval from concerned approval agency of tendered item12. Commercial documents such as GSTIN registration13. PAN card14. Udyam Registration Number & Certificate15. Current and Valid Registration certificates of Indian Railways indicating trade groups of items16. Certificate of registration as MSE from the organizations indicating category of ownership (SC/ST/others) and validity of registration (if applicable)17. Bidder''s own Drawing/Specification18. Product catalogue19. Technical Data-sheet of their quoted item20. Deviation/alternative design comparison-chart for proving equivalence of quoted product with respect to the drawing/specification of tender21. Other relevant document(s) to establish the credentials of the bidder regarding technical capability and financial capacity to manufacture & supply the tendered item to Purchaser22. Sister-concerns participation details23. Declaration about non-participation of sister-concerns24. Certificate confirming that the bidder is not from a country which shares a land border with India25. Evidence of valid registration by the Competent Authority (if applicable)26. Details of outstanding orders on them for this item27. Monthly capacity for supplying this item to PLW28. Complete address of place where the item will be inspected29. Complete address of place(s) where the item will be manufactured in India or where local value addition is made in India30. Copy of the e-bid signed with the Digital Signature of the tenderer in IREPS website31. Tender specific authorization from the OEM with its name and address32. UDYAM Registration Certificate33. Copy of GSTIN registration, PAN card34. Certificate of Local content35. IEEMA Circular letter no. 69/DIV/IEL/05 DT.16/03/11', '2026-07-11 09:27:27.056', '2026-07-11 09:27:27.056', NULL, NULL, 'cable,conductors,date', NULL, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101333884', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
