INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1547, 28, 't-125', 'estimate for power supply to 01 no 20 kw ndlf connection to signature international school  at kushal grih nirman raipura raipur of smt nisha sharma sector 01 agroha colony  raipura raipur under changorabhata zone city dn west raipur 78 064 5146 26 0003 dt 020626 r46064260060  64 07 i estimate for power supply to 03 nos dlf connection applied for 800 kw load at silver spring geetanjali nagar  under developed colony  under shankar nagar zone of city dn  east  raipur 78 064 5145 26 0001 dt 230626 r45064260159  64 08 i', '2026-07-28 18:30:00', 'india', 'chhattisgarh state power distribution company limited', '0', '0', NULL, NULL, '0', NULL, '2026-07-13 08:06:06.378', '2026-07-13 08:13:22.336', 'The tender brief is not explicitly for the supply of any eligible cables or conductors; it primarily discusses power supply connections without mentioning related eligible products.', false, 'cable', NULL, '290397', NULL, 'INR', 'Download Link', NULL, NULL, '10-07-2026', 'electrical work, transmission line', NULL, NULL, '98302959', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1213, 18, 'DGVCL/O&M/GWFCM/2026-27/Limbayat-A:318016:', 'site survey including underground utility verification, engineering, procurement, supply, loading, transportation, unloading, insurance, delivery at site, handling, storage, installation, testing, commissioning including documentation of all items/material required to complete works for turnkey based contract for conversion of existing lt line network including consumer service lines into under ground cable network using fsp/msp & ring main system at limbayat-a sub-division of pandesara division of surat city circle and anywhere in surat district under dgvcl with gis mapping / geo urja mapping (developed by guvnl) and asset tagging under gujarat wire free city mission (gwfcm).', '2026-07-22 18:30:00', 'Surat, Gujarat, India', 'Dakshin Gujarat Vij Company Limited', '11800', '4278625', '-', NULL, NULL, '• Format for Bidder Information Sheet
• Self-certified copy of the document to establish legal status of the firm viz. Certificate of Incorporation issued under the Companies Act / The Limited Liability Partnership Act / Partnership deed etc. as applicable
• Self certified copy of PAN
• Self certified copy of GST Registration
• Self certified copy in support of MSME, if applicable
• Organizational chart including a list of Board of Directors/ Key Management Personnels
• Joint Venture Agreement
• Details/ Data and documentary evidence in support of meeting the Qualification Requirement
• Format for the Bidder (Single Firm / Partner(s) in case of Joint Venture) for technical experience in compliance to para 2.1 of Section-2
• Format for the Bidder (Single Firm / Partner(s) in case of Joint Venture) for financial/ commercial experience in compliance to para 2.2.1, 2.2.2, 2.2.3 of Section-2
• Certificate from Banker indicating various fund based/non fund based limits sanctioned to the bidder and the extent of utilization as on date
• Complete annual reports together with Audited statement of accounts of the company for last five years of its own (separate) immediately preceding the date of submission of bid
• Integrity Pact
• Self-certified copy of the document to establish legal status of the firm viz. Certificate of Incorporation issued under The Companies Act / The Limited Liability Partnership Act / Partnership deed etc. as applicable
• Self-certified copy of PAN
• Self-certified copy of GST Registration
• Self-certified copy in support of MSME, if applicable
• Affidavit of Self certification regarding Local Content in line with PPP-MII order and #MoP Order/DoT order
• Format for details of the location(s) at which value addition is made
• Format of Alternative, Deviations and Exceptions to the Provisions of RFB Document
• Work Completion Schedule
• Guarantee Declaration
• Information regarding Ex-employees of XXXXX (Name of Employer) in our Organization
• Format for Price Adjustment Data
• Format of Option for Initial Advance (either Interest Bearing Initial Advance or No Initial Advance) and Information for E-payment, PF details and declaration regarding Micro/Small & Medium Enterprises
• Format of Declaration for tax exemptions, reductions, allowances or benefits
• Bank Guarantee verification Check list
• List of Special Maintenance Tools & Tackles included in bid price
• List of Special Maintenance Tools & Tackles not included in bid price
• Format of Additional Information
• Format of Power of Attorney by Each Member/ Partner of The Joint Venture in favor of Lead Member/ Partner
• Format of Joint Deed of Undertaking by the Joint Venture Partners/ Members
• Format for Details/ Data and Documentary Evidence in support of meeting the Qualification Requirement
• Format B: Format for the Bidder (Single Firm / Partner(s) in case of Joint Venture) for financial/ commercial experience in compliance to para 2.2.1, 2.2.2, 2.2.3 of Section-2
• Certificate from Banker indicating various fund based/non fund based limits sanctioned to the bidder and the extent of utilization as on date
• Complete annual reports together with Audited statement of accounts of the company for last five years of its own (separate) immediately preceding the date of submission of bid
• Format of Bought-out & Sub-contracted Items
• Format of Undertaking on Compliance of Terms & Conditions of the Bidding Documents including Scope of Work and other related requirements
• Format of Integrity Pact
• Format of Safety Plan
• Annexure – 1A (SP)
• Annexure – 1B (SP)
• Annexure – 2 (SP)
• Annexure – 3 (SP)
• Annexure – 4 (SP)
• Annexure – 5A (SP)
• Annexure – 5B (SP)
• Annexure – 6 (SP)
• Annexure – 7 (SP)
• Annexure – 10A (SP)
• Annexure – 10B (SP)
• Form of Joint Deed of Undertaking by the Sub-Contractor alongwith the Contractor
• Format for Evidence of Access to or Availability of Credit/Facilities
• Form of Operational Acceptance
• Form of Safety Plan to be Submitted by the Contractor within Sixty Days of Award of Contract
• Check List for Safety Plan
• Annexure – 1A (SP)
• Annexure – 1B (SP)
• Annexure – 2 (SP)
• Annexure – 3 (SP)
• Annexure – 4 (SP)
• Annexure – 5A (SP)
• Annexure – 5B (SP)
• Annexure – 6 (SP)
• Annexure – 7 (SP)
• Annexure – 8 (SP)
• Annexure – 9 (SP)
• Annexure – 10A (SP)
• Annexure – 10B (SP)', '2026-07-13 07:02:29.497', '2026-07-13 07:26:28.126', 'The tender brief describes a turnkey contract involving installation and related services but does not clearly indicate the supply of eligible power cables or conductors.', false, 'cable,conductors', NULL, '213931235', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '101728611', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
