INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1280, 18, 'BSD/HT-LT-TC/2026-27/N-Proc./PR- 229803:321905:', 'arc for erection of ht/lt and tc and maintenance work at laying and maintenance of ug 11 kv xlpe cable for si,skjy & nd schemes and maintenance only, including supply & erection of cable joint kit as and when required basis at asoder s dn & any other sdn.of borsad division area. of the all scheme for asoder & any other sub division under borsad do', '2026-07-28 18:30:00', 'Anand, Gujarat, India', 'Madhya Gujarat Vij Company Limited', '1770', '0', '-', NULL, NULL, '• Tender Fee payment receipt (online payment or Money receipt in original / self-certified copy for cash payment)
• EMD payment receipt (RTGS/NEFT)
• UDYAM REGISTRATION CERTIFICATE (for exemption from EMD)
• SSI/MSME Part-II/Udhyog Aadhar registration certificate (for exemption from EMD)
• Udyam Registration Certificate (for exemption from EMD)
• Udyam Registration Certificate (for exemption from EMD)
• CSPO / NSIC / DGS&D Registration Certificates (for exemption from EMD)
• Notarized copies of UDYAM REGISTRATION CERTIFICATE
• Notarized copies of SSI/MSME Part-II/Udhyog Aadhar
• Notarized copies of Udyam Registration Certificate
• Notarized copies of CSPO / NSIC / DGS&D Registration Certificates
• Work order copies for experienced contractors
• Experience certificate indicating order number and value for experienced contractors
• Electrical contractor''s license (for inexperienced contractors)
• Work order copies (for regular contractors in underground network)
• Experience certificate regarding execution of work of laying of pipe line (for regular contractors in underground network)
• Electrical contractor''s license (for regular contractors in underground network)
• Electrical contractor''s license (for new contractors in underground network)
• Certificate of work experience issued by Engineer in charge showing length of cable/pipe line in KM
• Tender notice & General Instructions
• Pre qualification / eligible criteria documents
• Scope & Specification of Work and General Terms and Conditions
• Commercial Terms and Conditions
• Schedule-B
• Digital map of underground network with GPS instrument
• GPS instrument accuracy certificate
• Valid exemption Certificates duly notarized (if applicable for EMD)
• Copy of valid E. P. F. Registration
• Copy of valid GST Registration Certificate
• Copy of valid PAN card
• Copy of valid Labour Insurance Policy
• Latest bank solvency certificate (minimum 20% of Tender cost)
• Work order copies for similar items executed by them
• Test Certificates for materials
• Indemnity Bond on stamp paper of Rs. 300/-
• Workmen''s Compensation Fund and Employers Liability Insurance
• Contractor''s license as per state Govt.
• Bank Solvency Certificate
• Registration of line / cable laying work certificate
• Experience certificate
• Registered GST No.
• E.P.F. Registration certificate
• I.T. Dept Pan-Card
• EMD receipt (for submission online)
• Bank Guarantee format for EMD
• Banker''s Undertaking for Performance Guarantee
• Banker''s Undertaking for Warrantee Period Guarantee
• Contractor''s declaration regarding employee interest in tendering company', '2026-07-13 07:02:45.258', '2026-07-13 07:28:22.107', 'The tender brief primarily focuses on installation, maintenance, and erection work and only mentions the supply of a cable joint kit, without explicitly including the supply of eligible power cables or conductors.', false, 'cable,conductors', NULL, '3998848', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '102123547', 'NOT_DECIDED', 'NOT_DECIDED', 'NOT_DECIDED', NULL, NULL, NULL, NULL, NULL);
