INSERT INTO public.non_gem_tenders (id, "fileId", "referenceNo", "tenderBrief", deadline, location, organization, "documentFees", emd, "msmeExemption", "startupExemption", quantity, checklist, "createdAt", "updatedAt", "aiRelevanceReason", "aiRelevanceValid", "excludedCategory", "tenderFileUrl", "estimatedBidValue", "assignedTo", currency, "downloadLink", "markedStatus", ready, "scrapedDate", "searchKey", "sheetStatus", source, "t247Id", apm, app, aps, "locationCount", state, "tenderStatusId", website, "utilityMappingId") VALUES (1287, 18, '2026_MES_776477_1', 'repair/ maint and replacement of lt cables, lt oh lines, mccbs, panels and connected items at sarna enclave, demo sqn, vindhya vihar, amn dump, ace, goswami enclave, aro, eme wksp, supply depot, jak li, demo bty and mes colonies under ge (awc) mhow', '2026-07-26 18:30:00', 'Indore, Madhya Pradesh, India', 'Military Engineer Services', '500', '70000', '-', NULL, NULL, '• Enlistment letter issued by the Registering Authority duly renewed for the cycle period in vogue
• Scanned copy of DD/Bankers Cheque toward cost of tender and EMD instrument in case SSD bond is not signed at the time of registration
• Copy of Police Verification Report/Police Clearance Certificate/Character Certificate from the Police Authority of the area where the registered office of the firm is located/notarized copy of valid passport of Proprietor/each Partner/each Director
• All documents required for enlistment in MES for the class mentioned in Para 8(b) above as per Para 1.5 of Section 1 of MES Manual on Contracts 2020
• Details of works being executed in MES, if any
